    21	
    22	    @Override
    23	    public void send(Channel channel, String to, String subject, String body) {
    24	        try (PreparedStatement st = db.connection().prepareStatement(
    25	                "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?)")) {
    26	            st.setString(1, channel.name());
    27	            st.setString(2, to);
    28	            st.setString(3, subject);
    29	            st.setString(4, body);
    30	            st.executeUpdate();
    31	        } catch (SQLException e) {
    32	            throw new IllegalStateException(e);
    33	        }
    34	    }
    35	
    36	    public List<Message> findAll() {
    37	        try (PreparedStatement st = db.connection().prepareStatement(
    38	                "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
    39	             ResultSet rs = st.executeQuery()) {
    40	            List<Message> messages = new ArrayList<>();
    41	            while (rs.next()) {
    42	                messages.add(new Message(rs.getLong("id"), Channel.valueOf(rs.getString("channel")),
    43	                        rs.getString("recipient"), rs.getString("subject"), rs.getString("body")));
    44	            }
    45	            return messages;
    46	        } catch (SQLException e) {
    47	            throw new IllegalStateException(e);
    48	        }
    49	    }
