     7	
     8	/** Preço de uma estadia. */
     9	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    10	
    11	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
    12	
    13	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    14	        BigDecimal subtotal = Money.ZERO;
    15	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    16	            subtotal = subtotal.add(nightPrice(room, night));
    17	        }
    18	        BigDecimal discount = plan.discountOn(subtotal);
    19	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    20	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    21	    }
    22	
    23	    static BigDecimal nightPrice(Room room, LocalDate night) {
    24	        BigDecimal rate = room.nightlyRate();
    25	        return Money.scale(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    26	    }
    27	
    28	    static boolean isHighSeason(LocalDate night) {
    29	        Month month = night.getMonth();
    30	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    31	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    32	    }
    33	}
