    23	    public Reservation(Long id, Room room, String guestName, String guestEmail, String guestCpf,
    24	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan, Quote quote,
    25	                       ReservationStatus status, BigDecimal amountPaid, BigDecimal refund) {
    26	        this.id = id;
    27	        this.room = room;
    28	        this.guestName = guestName;
    29	        this.guestEmail = guestEmail;
