    33	        this.guests = guests;
    34	        this.ratePlan = ratePlan;
    35	        this.quote = quote;
    36	        this.status = status;
    37	        this.amountPaid = amountPaid;
    38	        this.refund = refund;
    39	    }
    40	
    41	    /** Nova reserva pendente; valida a capacidade do quarto. */
    42	    public static Reservation open(Room room, String guestName, String guestEmail, String guestCpf,
    43	                                   LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    44	        if (guests > room.capacity()) {
    45	            throw new PousadaException(ErrorCode.CAPACITY_EXCEEDED,
    46	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    47	        }
    48	        Quote quote = Quote.of(room, checkIn, checkOut, ratePlan);
    49	        return new Reservation(null, room, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    50	                ratePlan, quote, ReservationStatus.PENDING, Money.ZERO, null);
    51	    }
    52	
    53	    public Reservation withId(long newId) {
    54	        return new Reservation(newId, room, guestName, guestEmail, guestCpf, checkIn, checkOut, guests,
    55	                ratePlan, quote, status, amountPaid, refund);
    56	    }
    57	
    58	    public void confirm() {
    59	        requireStatus("confirmada", ReservationStatus.PENDING);
    60	        amountPaid = quote.total();
    61	        status = ReservationStatus.CONFIRMED;
    62	    }
    63	
    64	    public void registerCheckIn() {
    65	        requireStatus("feito check-in", ReservationStatus.CONFIRMED);
    66	        status = ReservationStatus.CHECKED_IN;
    67	    }
    68	
    69	    public void registerCheckOut() {
    70	        requireStatus("feito check-out", ReservationStatus.CHECKED_IN);
    71	        status = ReservationStatus.CHECKED_OUT;
    72	    }
    73	
    74	    public void cancel() {
    75	        requireStatus("cancelada", ReservationStatus.PENDING, ReservationStatus.CONFIRMED);
    76	        refund = ratePlan.refundFor(amountPaid);
    77	        status = ReservationStatus.CANCELLED;
    78	    }
    79	
    80	    /** Só reservas pagas têm comprovante. */
    81	    public Receipt receipt() {
    82	        if (!status.isPaid()) {
    83	            throw new PousadaException(ErrorCode.OPERATION_NOT_ALLOWED,
    84	                    "Só reservas pagas têm comprovante; situação atual: " + status);
    85	        }
