     1	package br.com.marealta.pousada.notification;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	import java.util.function.Consumer;
     6	
     7	/** Quem quer saber de um acontecimento se inscreve aqui; quem o provoca só o publica. */
     8	public class EventBus {
     9	
    10	    private record Subscription<E>(Class<E> type, Consumer<E> handler) {
    11	        void deliver(Object event) {
    12	            if (type.isInstance(event)) {
    13	                handler.accept(type.cast(event));
    14	            }
    15	        }
    16	    }
    17	
    18	    private final List<Subscription<?>> subscriptions = new ArrayList<>();
    19	
    20	    public <E> void subscribe(Class<E> type, Consumer<E> handler) {
    21	        subscriptions.add(new Subscription<>(type, handler));
    22	    }
    23	
    24	    public void publish(Object event) {
    25	        subscriptions.forEach(s -> s.deliver(event));
    26	    }
    27	}
