     1	package br.com.marealta.pousada.persistence;
     2	
     3	import com.zaxxer.hikari.HikariConfig;
     4	import com.zaxxer.hikari.HikariDataSource;
     5	
     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	import java.util.function.Supplier;
    10	
    11	/** Conexão com o PostgreSQL e transações. Os repositórios usam a conexão da transação em andamento. */
    12	public class Database implements AutoCloseable {
    13	
    14	    private static final String SCHEMA = """
    15	            CREATE TABLE IF NOT EXISTS reservations (
    16	                id BIGSERIAL PRIMARY KEY,
    17	                room_number INT NOT NULL,
    18	                guest_name TEXT NOT NULL,
    19	                guest_email TEXT NOT NULL,
    20	                guest_cpf TEXT NOT NULL,
    21	                check_in DATE NOT NULL,
    22	                check_out DATE NOT NULL,
    23	                guests INT NOT NULL,
    24	                rate_plan TEXT NOT NULL,
    25	                nights INT NOT NULL,
    26	                subtotal NUMERIC(12,2) NOT NULL,
    27	                discount NUMERIC(12,2) NOT NULL,
    28	                total NUMERIC(12,2) NOT NULL,
    29	                status TEXT NOT NULL,
    30	                amount_paid NUMERIC(12,2) NOT NULL,
    31	                refund NUMERIC(12,2)
    32	            );
    33	            CREATE INDEX IF NOT EXISTS reservations_room_dates ON reservations (room_number, check_in, check_out);
    34	            CREATE TABLE IF NOT EXISTS messages (
    35	                id BIGSERIAL PRIMARY KEY,
    36	                channel TEXT NOT NULL,
    37	                recipient TEXT NOT NULL,
    38	                subject TEXT NOT NULL,
    39	                body TEXT NOT NULL
    40	            );
    41	            """;
    42	
    43	    private final HikariDataSource dataSource;
    44	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
    45	
    46	    public Database(String url, String user, String password) {
    47	        HikariConfig config = new HikariConfig();
    48	        config.setJdbcUrl(url);
    49	        config.setUsername(user);
    50	        config.setPassword(password);
    51	        config.setMaximumPoolSize(10);
    52	        config.setInitializationFailTimeout(60_000);
    53	        this.dataSource = new HikariDataSource(config);
    54	        createSchema();
    55	    }
    56	
    57	    private void createSchema() {
    58	        transaction(() -> {
    59	            try (Statement st = connection().createStatement()) {
    60	                // evita que duas instâncias subindo juntas criem as tabelas ao mesmo tempo
    61	                st.execute("SELECT pg_advisory_xact_lock(7070)");
    62	                st.execute(SCHEMA);
    63	            } catch (SQLException e) {
    64	                throw new IllegalStateException(e);
    65	            }
    66	            return null;
    67	        });
    68	    }
    69	
    70	    public Connection connection() {
    71	        Connection connection = current.get();
    72	        if (connection == null) {
    73	            throw new IllegalStateException("Operação de banco fora de uma transação");
    74	        }
    75	        return connection;
    76	    }
    77	
    78	    public <T> T transaction(Supplier<T> work) {
    79	        if (current.get() != null) {
    80	            return work.get();
    81	        }
    82	        try (Connection connection = dataSource.getConnection()) {
    83	            connection.setAutoCommit(false);
    84	            current.set(connection);
    85	            try {
    86	                T result = work.get();
    87	                connection.commit();
    88	                return result;
    89	            } catch (RuntimeException | Error e) {
    90	                connection.rollback();
    91	                throw e;
    92	            } finally {
    93	                current.remove();
    94	            }
    95	        } catch (SQLException e) {
    96	            throw new IllegalStateException(e);
    97	        }
    98	    }
    99	
   100	    @Override
   101	    public void close() {
   102	        dataSource.close();
   103	    }
   104	}
