    26	        this.db = db;
    27	    }
    28	
    29	    /** Impede que duas transações reservem o mesmo quarto ao mesmo tempo. */
    30	    public void lockRoom(int roomNumber) {
    31	        try (PreparedStatement st = db.connection().prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    32	            st.setLong(1, roomNumber);
    33	            st.execute();
    34	        } catch (SQLException e) {
    35	            throw new IllegalStateException(e);
    36	        }
    37	    }
    38	
    39	    public boolean isRoomBooked(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
    40	        try (PreparedStatement st = db.connection().prepareStatement(
    41	                "SELECT 1 FROM reservations WHERE room_number = ? AND status <> 'CANCELLED' "
    42	                        + "AND check_in < ? AND check_out > ?")) {
    43	            st.setInt(1, roomNumber);
    44	            st.setObject(2, checkOut);
    45	            st.setObject(3, checkIn);
    46	            try (ResultSet rs = st.executeQuery()) {
    47	                return rs.next();
    48	            }
    49	        } catch (SQLException e) {
    50	            throw new IllegalStateException(e);
    51	        }
    52	    }
    53	
    54	    public Reservation insert(Reservation r) {
    55	        try (PreparedStatement st = db.connection().prepareStatement(
    56	                "INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out, "
    57	                        + "guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund) "
    58	                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
    59	                Statement.RETURN_GENERATED_KEYS)) {
    60	            st.setInt(1, r.room().number());
    61	            st.setString(2, r.guestName());
    62	            st.setString(3, r.guestEmail());
    63	            st.setString(4, r.guestCpf());
    64	            st.setObject(5, r.checkIn());
    65	            st.setObject(6, r.checkOut());
    66	            st.setInt(7, r.guests());
    67	            st.setString(8, r.ratePlan().name());
    68	            st.setInt(9, r.quote().nights());
    69	            st.setBigDecimal(10, r.quote().subtotal());
    70	            st.setBigDecimal(11, r.quote().discount());
    71	            st.setBigDecimal(12, r.quote().total());
    72	            st.setString(13, r.status().name());
    73	            st.setBigDecimal(14, r.amountPaid());
    74	            st.setBigDecimal(15, r.refund());
    75	            st.executeUpdate();
    76	            try (ResultSet keys = st.getGeneratedKeys()) {
    77	                keys.next();
    78	                return r.withId(keys.getLong("id"));
    79	            }
    80	        } catch (SQLException e) {
    81	            throw new IllegalStateException(e);
    82	        }
    83	    }
    84	
    85	    public void update(Reservation r) {
    86	        try (PreparedStatement st = db.connection().prepareStatement(
    87	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    88	            st.setString(1, r.status().name());
    89	            st.setBigDecimal(2, r.amountPaid());
    90	            st.setBigDecimal(3, r.refund());
    91	            st.setLong(4, r.id());
    92	            st.executeUpdate();
    93	        } catch (SQLException e) {
    94	            throw new IllegalStateException(e);
    95	        }
    96	    }
    97	
    98	    /** Busca e trava a linha até o fim da transação. */
    99	    public Optional<Reservation> findById(long id) {
   100	        return query("SELECT " + COLUMNS + " FROM reservations WHERE id = ? FOR UPDATE", id).stream().findFirst();
   101	    }
   102	
   103	    /** Reservas pagas que ocupam um quarto na noite, por número do quarto. */
   104	    public List<Reservation> findPaidOccupying(LocalDate night) {
   105	        return query("SELECT " + COLUMNS + " FROM reservations WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') "
   106	                + "AND check_in <= ? AND check_out > ? ORDER BY room_number, id", night, night);
   107	    }
   108	
   109	    /** Reservas que começam no período e deixaram dinheiro com a pousada. */
   110	    public List<Reservation> findRetainingMoney(LocalDate from, LocalDate toExclusive) {
   111	        return query("SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   112	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id", from, toExclusive);
   113	    }
   114	
   115	    private List<Reservation> query(String sql, Object... params) {
   116	        try (PreparedStatement st = db.connection().prepareStatement(sql)) {
   117	            for (int i = 0; i < params.length; i++) {
   118	                st.setObject(i + 1, params[i]);
   119	            }
   120	            try (ResultSet rs = st.executeQuery()) {
   121	                List<Reservation> found = new ArrayList<>();
   122	                while (rs.next()) {
   123	                    found.add(read(rs));
   124	                }
   125	                return found;
   126	            }
   127	        } catch (SQLException e) {
   128	            throw new IllegalStateException(e);
   129	        }
   130	    }
   131	
   132	    private Reservation read(ResultSet rs) throws SQLException {
   133	        Room room = Room.find(rs.getInt("room_number")).orElseThrow();
   134	        Quote quote = new Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"),
   135	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   136	        return new Reservation(rs.getLong("id"), room, rs.getString("guest_name"), rs.getString("guest_email"),
   137	                rs.getString("guest_cpf"), rs.getObject("check_in", LocalDate.class),
   138	                rs.getObject("check_out", LocalDate.class), rs.getInt("guests"),
   139	                RatePlan.valueOf(rs.getString("rate_plan")), quote,
   140	                ReservationStatus.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"),
   141	                rs.getBigDecimal("refund"));
   142	    }
   143	}

